mapper.select:
select TOP 1 DATA_ID,WORK_DATE,FILE_NAME,TARGET_PATH,SND_IP,REC_IP,UPLOAD_TIME,UPLOADER,FILLER1,FILLER2,FILLER3
from DIGITAL_TEMPLATE_UPLOADLOG
where FILLER1 = #{FILLER1,jdbcType=VARCHAR}
  and FILE_NAME = #{FILE_NAME,jdbcType=VARCHAR}
  and UPLOAD_TIME like #{UPLOAD_TIME,jdbcType=VARCHAR}
order by UPLOAD_TIME desc

select  DATA_ID,WORK_DATE,FILE_NAME,TARGET_PATH,SND_IP,REC_IP,UPLOAD_TIME,UPLOADER,FILLER1,FILLER2,FILLER3
from DIGITAL_TEMPLATE_UPLOADLOG
where FILLER1 = #{FILLER1,jdbcType=VARCHAR}
  and FILE_NAME = #{FILE_NAME,jdbcType=VARCHAR}
  and UPLOAD_TIME like #{UPLOAD_TIME,jdbcType=VARCHAR}
  and rownum=1
order by UPLOAD_TIME desc

mapper.update:
update DIGITAL_TEMPLATE_UPLOADLOG
    set FILLER1 = #{FILLER1,jdbcType=VARCHAR}
where DATA_ID = #{DATA_ID,jdbcType=VARCHAR}
